function initLyrics() {
            track.innerHTML = '';
            lineElements = [];
            allSyllablesFlat = [];

            lyricsData.forEach((lineArray, lIdx) => {
                const div = document.createElement('div');
                div.className = 'line';
                div.id = 'line-' + lIdx;

                lineArray.forEach((syl, sIdx) => {
                    const span = document.createElement('span');
                    span.className = 'syllable';
                    span.id = `syl-${lIdx}-${sIdx}`;
                    span.innerHTML = syl.text + (syl.space_after ? "&nbsp;" : "");
                    div.appendChild(span);

                    allSyllablesFlat.push({
                        time: syl.time,
                        lineIndex: lIdx,
                        sylIndex: sIdx,
                        element: span,
                        dataRef: syl
                    });
                });

                track.appendChild(div);
                lineElements.push(div);
            });
            updateLinePosition(0);
            setTimeout(cacheSyllablePositions, 100);
        }

function cacheSyllablePositions() {
            allSyllablesFlat.forEach(item => {
                const rect = item.element.getBoundingClientRect();
                item.cachedX = rect.left + (rect.width / 2);
                item.cachedY = rect.top - 20;
            });
        }

        window.addEventListener('resize', cacheSyllablePositions);

function updateLinePosition(index) {
            if (index < 0 || index >= lineElements.length) return;

            const activeLine = lineElements[index];
            const offset = activeLine.offsetTop;
            track.style.transform = `translateY(-${offset}px)`;

            lineElements.forEach((el, i) => {
                if (i < index) {
                    el.className = 'line past';
                } else if (i === index) {
                    el.className = 'line active';
                } else {
                    el.className = 'line';
                }
            });
            // Re-cache positions after scroll/layout shift
            setTimeout(cacheSyllablePositions, 300);
        }

