function t(key) {
        return state.i18nData[state.langU][key] || state.i18nData['fr'][key] || key;
    }

    document.getElementById('uiLangSelect').addEventListener('change', (e) => {
        state.langU = e.target.value;
        updateUI();
        saveState();
    });

function saveState() {
        if (state.lyricsData && state.lyricsData.length > 0) {
            localStorage.setItem('karaoke_lyrics', JSON.stringify(state.lyricsData));
        }
        localStorage.setItem('karaoke_audio_name', state.audioFileName || '');
        localStorage.setItem('karaoke_lang_ui', state.langU);
        localStorage.setItem('karaoke_offset', document.getElementById('introOffset').value);
        localStorage.setItem('karaoke_raw_text', document.getElementById('lyricsInput').value);
    }

function loadState() {
        const savedLyrics = localStorage.getItem('karaoke_lyrics');
        if (savedLyrics) {
            state.lyricsData = JSON.parse(savedLyrics);
        }
        const savedAudio = localStorage.getItem('karaoke_audio_name');
        if (savedAudio) state.audioFileName = savedAudio;

        const savedLang = localStorage.getItem('karaoke_lang_ui');
        if (savedLang) {
            state.langU = savedLang;
            document.getElementById('uiLangSelect').value = savedLang;
        }

        const savedOffset = localStorage.getItem('karaoke_offset');
        if (savedOffset) {
            document.getElementById('introOffset').value = savedOffset;
        }

        const savedRaw = localStorage.getItem('karaoke_raw_text');
        if (savedRaw) {
            document.getElementById('lyricsInput').value = savedRaw;
        }

        if (state.lyricsData.length > 0) {
            renderEditor();
            updateUI();
        }
    }

    // Call load on startup
    window.addEventListener('DOMContentLoaded', loadState);

function updateUI() {
        document.querySelectorAll('[data-i18n]').forEach(el => {
            el.innerHTML = t(el.getAttribute('data-i18n'));
        });
        document.querySelectorAll('[data-i18n-ph]').forEach(el => {
            el.placeholder = t(el.getAttribute('data-i18n-ph'));
        });

        // Sync View dynamic titles
        const syncCont = document.getElementById('syncContent');
        if (syncCont && syncCont.querySelector('h3')) {
            syncCont.querySelector('h3').innerText = t('sync_title');
            syncCont.querySelector('p').innerText = t('sync_desc');
        }
    }

