function buildLineString(line) {
        let str = "";
        line.forEach((s, idx) => {
            str += s.text;
            if (s.space_after) str += " ";
            else if (idx < line.length - 1) str += "-";
        });
        return str;
    }

    const importHtmlBtn = document.getElementById('importHtmlBtn');
    const importHtmlInput = document.getElementById('importHtmlInput');

    importHtmlBtn.addEventListener('click', () => importHtmlInput.click());

    importHtmlInput.addEventListener('change', (e) => {
        const file = e.target.files[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = (evt) => {
            const content = evt.target.result;
            // Match "const data = [[...]];" or "const lyricsData = [[...]];"
            const match = content.match(/(?:const|var|let)\s+(?:lyricsData|data)\s*=\s*(\[\[[\s\S]*?\]\]);/);
            if (match && match[1]) {
                try {
                    const parsed = JSON.parse(match[1]);
                    state.lyricsData = parsed;
                    alert(t('alert_import_ok'));
                    renderEditor();
                    switchStep('edit');
                    saveState();
                } catch(err) {
                    alert(t('alert_import_err'));
                }
            } else {
                alert(t('alert_import_err') + " (No record found)");
            }
        };
        reader.readAsText(file);
        e.target.value = '';
    });

function parseLineString(str) {
        const words = str.trim().split(/\s+/);
        let line = [];
        words.forEach((w) => {
            const syls = w.split('-');
            syls.forEach((s, sIdx) => {
                if (s.trim().length > 0) {
                    line.push({
                        text: s.trim(),
                        space_after: sIdx === syls.length - 1,
                        time: 0
                    });
                }
            });
        });
        return line;
    }

