            document.querySelectorAll('.cal-line').forEach((l, i) => {
                l.classList.toggle('active', i === currentLineIdx);
                if (i === currentLineIdx) l.scrollIntoView({ behavior: 'smooth', block: 'center' });
            });
        }
    }

