function seekLine(dir) {
             const now = player.currentTime;
             let currentIdx = -1;
             data.forEach((line, lIdx) => { line.forEach(s => { if(now >= s.time && s.time > 0) currentIdx = lIdx; }); });

             let targetIdx = currentIdx + dir;
             if (targetIdx < 0) targetIdx = 0;
             if (targetIdx >= data.length) targetIdx = data.length - 1;

             // Find first syllable with time in target line
             const targetLine = data[targetIdx];
             const firstSyl = targetLine.find(s => s.time > 0);
             if (firstSyl) {
                 player.currentTime = firstSyl.time;
                 if (player.paused) player.play();
             }
        }

        document.getElementById('prevBtn').onclick = () => seekLine(-1);
        document.getElementById('nextBtn').onclick = () => seekLine(1);

        window.addEventListener('keydown', (e) => {
            if(e.code === 'Space' || e.code === 'Enter') {
                e.preventDefault();
                if(player.paused) player.play(); else player.pause();
            }
            if(e.code === 'ArrowLeft') seekLine(-1);
            if(e.code === 'ArrowRight') seekLine(1);
        });

        // Auto-pause at start to let teacher lead
        console.log('Player ready with dynamic scrolling');
