function parseLineString(str) {
        const words = str.trim().split(/\\s+/);
        let line = [];
        words.forEach((w) => {
            const syls = w.split('-');
            syls.forEach((s, sIdx) => {
                if (s.trim().length > 0) {
                    line.push({
                        text: s.trim(),
                        space_after: sIdx === syls.length - 1,
                        time: 0
                    });
                }
            });
        });
        return line;
    }

