function buildMsgHTML(role, content, personaId) {
    if (role === 'user') {
        return `<div class="msg user" style="align-self:flex-end; background:#333; color:#ddd;">${content}</div>`;
    } else {
        // C'est le bot : on affiche l'avatar à gauche + la bulle
