      }
      if (x >= 1 && x < w - 1 && y1 >= 1 && y1 < h - 1) {
        if (Math.abs(x - (x0 + x1) / 2) > 2) tiles[y1][x] = 1;
      }
    }
    for (let y = y0; y <= y1; y += 1) {
      if (y >= 1 && y < h - 1 && x0 >= 1 && x0 < w - 1) {
