@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Outfit:wght@400;700;800&display=swap');

:root {
  /* Premium Dark Theme Palette */
  --bg-gradient-start: #0f172a;
  --bg-gradient-end: #1e1b4b; /* Deep Indigo */

  --primary: #818cf8; /* Indigo 400 */
  --primary-glow: rgba(129, 140, 248, 0.5);
  --secondary: #94a3b8; /* Slate 400 */

  --surface: rgba(30, 41, 59, 0.7); /* Glassy Surface */
  --surface-border: rgba(255, 255, 255, 0.1);
  --surface-hover: rgba(51, 65, 85, 0.8);

  --text: #f1f5f9;
  --text-muted: #94a3b8;

  /* Status Colors */
  --status-neutral-bg: rgba(255, 255, 255, 0.05);
  --status-neutral-text: #cbd5e1;

  --status-active-bg: rgba(59, 130, 246, 0.2);
  --status-active-text: #60a5fa;

  --status-success-bg: rgba(34, 197, 94, 0.2);
  --status-success-text: #4ade80;

  /* Layout */
  --max-width: 1200px;
  --radius-lg: 16px;
  --radius-md: 8px;
  --shadow-lg: 0 10px 30px -10px rgba(0, 0, 0, 0.5);
}

body {
  font-family: 'Inter', sans-serif;
  background: linear-gradient(135deg, var(--bg-gradient-start), var(--bg-gradient-end));
  color: var(--text);
